#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

// Настройки OLED экрана
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET    -1
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

// Пин 8 для динамика
const int buzzerPin = 8; 

// Ноты для мелодии "Life Goes On"
#define NOTE_G4  392
#define NOTE_A4  440
#define NOTE_B4  494
#define NOTE_C5  523
#define NOTE_D5  587
#define NOTE_E5  659
#define NOTE_FS5 740
#define NOTE_G5  784

int melody[] = {
  NOTE_B4, NOTE_D5, NOTE_B4, NOTE_A4, 0,
  NOTE_B4, NOTE_D5, NOTE_B4, NOTE_A4, 0,
  NOTE_G4, NOTE_B4, NOTE_D5, NOTE_B4, NOTE_A4, 0,
  NOTE_G4, NOTE_B4, NOTE_D5, NOTE_G4, NOTE_B4, NOTE_D5, NOTE_G5, NOTE_FS5, NOTE_E5, NOTE_D5, 0,
  NOTE_B4, NOTE_D5, NOTE_B4, NOTE_A4, NOTE_G4, NOTE_A4, NOTE_G4, 0
};

int noteDurations[] = {
  4, 4, 4, 2, 4,  4, 4, 4, 2, 4,
  4, 4, 4, 4, 2, 4,
  8, 8, 8, 8, 8, 8, 8, 8, 8, 4, 4,
  4, 4, 4, 4, 4, 4, 2, 2
};

void setup() {
  // Запуск экрана (в симуляторе Wokwi адрес всегда 0x3C)
  if(!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { 
    for(;;); 
  }

  display.clearDisplay();
  pinMode(buzzerPin, OUTPUT);
}

// Функция, которая рисует ретро-телевизор и прыгающий эквалайзер
void drawEqualizer(bool isPlaying) {
  display.clearDisplay();

  // Рисуем рамку корпуса телевизора
  display.drawRect(0, 0, 128, 64, SSD1306_WHITE);

  // Рисуем "ножки" телевизора внизу экрана
  display.drawLine(10, 63, 5, 60, SSD1306_WHITE);
  display.drawLine(118, 63, 123, 60, SSD1306_WHITE);

  // Рисуем маленькие кнопочки переключения каналов справа
  display.drawRect(114, 10, 8, 6, SSD1306_WHITE);
  display.drawRect(114, 20, 8, 6, SSD1306_WHITE);
  display.drawRect(114, 30, 8, 6, SSD1306_WHITE);

  // Прыгающий эквалайзер из 5 полосок
  for (int i = 0; i < 5; i++) {
    int h = 0;
    if (isPlaying) {
      h = random(5, 42); // Полоски бешено скачут под музыку
    } else {
      h = 2; // Опускаются, когда тишина
    }
    display.fillRect(15 + (i * 18), 52 - h, 12, h, SSD1306_WHITE);
  }

  // Надпись сверху экрана
  display.setTextSize(1);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(22, 6);
  display.print("OLIVER TREE TV");

  display.display();
}

void loop() {
  // Всего в нашем припеве 35 элементов (ноты и паузы)
  for (int thisNote = 0; thisNote < 35; thisNote++) {
    int noteDuration = 850 / noteDurations[thisNote];

    if (melody[thisNote] == 0) {
      noTone(buzzerPin);
      drawEqualizer(false); 
      delay(noteDuration);
    } else {
      tone(buzzerPin, melody[thisNote], noteDuration);

      // Анимация прыжков внутри длительности одной ноты
      for(int i = 0; i < 4; i++) {
        drawEqualizer(true);
        delay(noteDuration / 4);
      }

      noTone(buzzerPin);
      drawEqualizer(false);
      delay(80); // Твоя фирменная душевная задержка после каждой ноты
    }
  }

  // Пауза 4 секунды между повторами припева
  unsigned long startTime = millis();
  while(millis() - startTime < 4000) {
    drawEqualizer(false); 
    delay(200);
  }
}
